  "$id": "schemas/worker-result.schema.json",
  "title": "WorkerResult",
  "description": "Schema for the result object returned by a worker agent after completing (or failing) a task.",
  "type": "object",
  "required": ["task_id", "attempt", "outcome", "artifact"],
  "additionalProperties": false,
  "properties": {
    "task_id": {
      "type": "string",
      "minLength": 1,
      "description": "Must echo the task_id from the engine brief."
    },
    "attempt": {
      "type": "integer",
      "minimum": 1,
      "description": "Which attempt number this result represents."
    },
    "outcome": {
      "type": "string",
      "enum": ["passed", "failed"],
      "description": "Whether the task passed or failed acceptance."
    },
    "artifact": {
      "type": "string",
      "minLength": 1,
      "description": "A non-blank string carrying the deliverable or evidence of work."
    },
    "critique": {
      "type": "string",
      "minLength": 1,
      "description": "Required when outcome is 'failed'; must not be present when outcome is 'passed'."
    },
    "question": {
      "type": "object",
      "description": "An optional clarifying question for the engine. Must not be present when outcome is 'passed'.",
      "required": ["question_id", "prompt"],
      "additionalProperties": false,
      "properties": {
        "question_id": {
          "type": "string",
          "minLength": 1
        },
        "prompt": {
          "type": "string",
          "minLength": 1
        }
      }
    }
  },
  "if": { "properties": { "outcome": { "const": "passed" } } },
  "then": {
    "not": {
      "anyOf": [
        { "required": ["critique"] },
        { "required": ["question"] }
      ]
    }
  },
  "else": {
    "required": ["critique"]
  }
}
"}
</tool_result>

